function dl(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function previewDownload(blob,name){
  const url=URL.createObjectURL(blob), type=blob.type||'';
  let body='';
  if(type.startsWith('image/')) body=`<img class="preview bigpreview" src="${url}" alt="Preview">`;
  else if(type==='application/pdf') body=`<iframe class="filepreview" src="${url}" title="PDF Preview"></iframe>`;
  else if(type.startsWith('text/')||/\.(txt|csv|json|xml|html|css|js)$/i.test(name)){
    const reader=new FileReader(); reader.onload=()=>showPreview(name,`<pre class="textpreview">${esc(String(reader.result))}</pre>`,blob,name); reader.readAsText(blob); return;
  } else body=`<div class="previewfile">📦<br><b>${esc(name)}</b><br><span class="muted">इस file का browser preview उपलब्ध नहीं है। Download करने से पहले file information यहाँ दिखाई जा रही है।</span></div>`;
  showPreview(name,body,blob,name);
}
function showPreview(name,body,blob,downloadName){
  const modal=document.createElement('div'); modal.className='previewmodal';
  modal.innerHTML=`<div class="previewbox"><button class="previewclose">×</button><h2>👁️ Preview</h2><div class="muted">${esc(downloadName)}</div><div class="previewarea">${body}</div><div class="actions"><button class="btn downloadnow">👁️ View Preview</button><button class="btn secondary previewclose2">Close</button></div></div>`;
  document.body.appendChild(modal);
  const close=()=>{modal.remove();setTimeout(()=>URL.revokeObjectURL(modal.dataset.url||''),100)};
  modal.querySelectorAll('.previewclose,.previewclose2').forEach(x=>x.onclick=close);
  modal.querySelector('.downloadnow').onclick=()=>dl(blob,downloadName);
  modal.dataset.url=(body.match(/src="([^"]+)/)||body.match(/src=\'([^\']+)/)||[])[1]||'';
  modal.onclick=e=>{if(e.target===modal)close()};
}
