 if(id==='textcsv'){$('#go').onclick=()=>{let d=$('#delim').value,t=$('#t').value.split(/\r?\n/).filter(Boolean).map(r=>r.split(d).map(v=>'"'+v.replaceAll('"','""')+'"').join(',')).join('\n');$('#r').innerHTML=`<div class="result"><pre>${esc(t)}</pre><button class="btn download" id="d">👁️ View Preview</button></div>`;$('#d').onclick=()=>dltxt(t,'converted.csv')};return}
 if(id==='json'){$('[data-j="format"]').onclick=()=>{try{$('#out').value=JSON.stringify(JSON.parse($('#t').value),null,2)}catch(e){toast('Invalid JSON')}};$('[data-j="minify"]').onclick=()=>{try{$('#out').value=JSON.stringify(JSON.parse($('#t').value))}catch(e){toast('Invalid JSON')}};$('[data-j="validate"]').onclick=()=>{try{JSON.parse($('#t').value);$('#out').value='Valid JSON ✓'}catch(e){$('#out').value='Invalid JSON: '+e.message}};$('#dl').onclick=()=>dltxt(out(),'formatted.json');return}
 if(id==='base64'){$('#enc').onclick=()=>$('#out').value=btoa(unescape(encodeURIComponent($('#t').value)));$('#dec').onclick=()=>{try{$('#out').value=decodeURIComponent(escape(atob($('#t').value)))}catch(e){toast('Invalid Base64')}};$('#dl').onclick=()=>dltxt(out(),'base64.txt');return}
 if(id==='urlcode'){$('#enc').onclick=()=>$('#out').value=encodeURIComponent($('#t').value);$('#dec').onclick=()=>{try{$('#out').value=decodeURIComponent($('#t').value)}catch(e){toast('Invalid URL encoding')}};$('#dl').onclick=()=>dltxt(out(),'url.txt');return}
 if(id==='htmlentity'){$('#enc').onclick=()=>$('#out').value=$('#t').value.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));$('#dec').onclick=()=>{let ta=document.createElement('textarea');ta.innerHTML=$('#t').value;$('#out').value=ta.value};$('#dl').onclick=()=>dltxt(out(),'html-entity.txt');return}
 if(id==='regex'){$('#go').onclick=()=>{try{let r=new RegExp($('#pat').value,$('#flags').value),t=$('#t').value,m=[...t.matchAll(r)];$('#r').innerHTML=`<div class="result">Matches: ${m.length}<br>${m.map(x=>esc(x[0])).join(', ')}</div>`}catch(e){toast('Invalid regex')}};return}
 if(id==='color'){$('#go').onclick=()=>{let hex=$('#hex').value.trim().replace('#','');if(/^[0-9a-f]{3}$/i.test(hex))hex=[...hex].map(x=>x+x).join('');if(!/^[0-9a-f]{6}$/i.test(hex))return toast('HEX सही दें');let n=parseInt(hex,16),r=n>>16,g=n>>8&255,b=n&255;let mx=Math.max(r,g,b)/255,mn=Math.min(r,g,b)/255,l=(mx+mn)/2,d=mx-mn,h=0,s=0;if(d){s=d/(1-Math.abs(2*l-1));if(mx===r)h=60*(((g-b)/255/d)%6);else if(mx===g)h=60*((b-r)/255/d+2);else h=60*((r-g)/255/d+4)}$('#rgb').value=`${r}, ${g}, ${b}`;$('#hsl').value=`${Math.round((h+360)%360)}, ${Math.round(s*100)}%, ${Math.round(l*100)}%`;$('#r').innerHTML=`<div class="result"><div style="width:100%;height:60px;border-radius:8px;background:#${hex}"></div>HEX: #${hex.toUpperCase()}<br>RGB: ${r}, ${g}, ${b}<br>HSL: ${Math.round((h+360)%360)}, ${Math.round(s*100)}%, ${Math.round(l*100)}%</div>`};return}
 if(id==='csvjson'){$('#go').onclick=()=>{let rows=$('#t').value.trim().split(/\r?\n/).map(x=>x.split(',')),h=rows.shift(),a=rows.map(r=>Object.fromEntries(h.map((k,i)=>[k.trim(),(r[i]||'').trim()])));$('#out').value=JSON.stringify(a,null,2)};$('#dl').onclick=()=>dltxt(out(),'data.json');return}
 if(id==='jsoncsv'){$('#go').onclick=()=>{try{let a=JSON.parse($('#t').value);if(!Array.isArray(a)||!a.length)throw 0;let h=[...new Set(a.flatMap(x=>Object.keys(x)))],q=v=>'"'+String(v??'').replaceAll('"','""')+'"';$('#out').value=[h.map(q).join(','),...a.map(x=>h.map(k=>q(x[k])).join(','))].join('\n')}catch(e){toast('JSON array of objects दें')}};$('#dl').onclick=()=>dltxt(out(),'data.csv');return}
 if(id==='uuid'){$('#go').onclick=()=>{let a=Array.from({length:+$('#n').value||1},()=>crypto.randomUUID());$('#out').value=a.join('\n')};$('#dl').onclick=()=>dltxt(out(),'uuid.txt');return}
 if(id==='random'){$('#go').onclick=()=>{let min=+$('#min').value,max=+$('#max').value,n=Math.min(1000,+$('#n').value||1),arr=[];if(max<min)return toast('Max >= Min रखें');if($('#unique').value==='yes'&&n>max-min+1)return toast('Unique count range से ज्यादा है');while(arr.length<n){let v=Math.floor(Math.random()*(max-min+1))+min;if($('#unique').value==='no'||!arr.includes(v))arr.push(v)}$('#out').value=arr.join('\n')};$('#dl').onclick=()=>dltxt(out(),'random.txt');return}
 if(id==='lorem'){$('#go').onclick=()=>{let words='lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor incididunt ut labore et dolore magna aliqua'.split(' '),ps=+$('#p').value,n=+$('#n').value,a=[];for(let p=0;p<ps;p++){let s=[];for(let j=0;j<n;j++){let len=8+Math.floor(Math.random()*8),z=[];for(let k=0;k<len;k++)z.push(words[Math.floor(Math.random()*words.length)]);s.push(z.join(' '))}a.push(s.map((x,i)=>i===0?x[0].toUpperCase()+x.slice(1)+'.':x+'.').join(' '))}$('#out').value=a.join('\n\n')};$('#dl').onclick=()=>dltxt(out(),'lorem.txt');return}
 if(id==='timestamp'){$('#toTs').onclick=()=>{let d=new Date($('#date').value);if(isNaN(d))return toast('Date चुनें');$('#r').innerHTML=`<div class="result">Unix seconds: ${Math.floor(d.getTime()/1000)}<br>Milliseconds: ${d.getTime()}</div>`};$('#toDate').onclick=()=>{let n=+$('#ts').value,d=new Date(n<1e12?n*1000:n);if(isNaN(d))return toast('Timestamp सही दें');$('#r').innerHTML=`<div class="result">${d.toString()}<br>${d.toISOString()}</div>`};return}
 if(id==='duration'){$('#go').onclick=()=>{let [ah,am]=$('#a').value.split(':').map(Number),[bh,bm]=$('#b').value.split(':').map(Number),a=ah*60+am,b=bh*60+bm;if(b<a&&$('#over').value==='yes')b+=1440;if(b<a)return toast('Overnight Yes करें');let m=b-a;result('#r',`${Math.floor(m/60)} hours ${m%60} minutes`,true)};return}
