 if(id==='tip'){$('#go').onclick=()=>{let b=+$('#bill').value,t=+$('#tip').value,p=+$('#people').value||1,tip=b*t/100,total=b+tip;result('#r',`Tip: ${money(tip)}<br>Total: ${money(total)}<br>Per person: ${money(total/p)}`,true)};return}
 if(id==='businessdays'){$('#go').onclick=()=>{let a=new Date($('#a').value),b=new Date($('#b').value);if(isNaN(a)||isNaN(b))return toast('Dates चुनें');if(a>b)[a,b]=[b,a];let n=0;for(let d=new Date(a);d<=b;d.setDate(d.getDate()+1)){let x=d.getDay();if(x!==0&&x!==6)n++}result('#r',`Business days: ${n}`,true)};return}
 if(id==='prime'){$('#go').onclick=()=>{let n=+$('#n').value,ok=n>=2;for(let i=2;i*i<=n&&ok;i++)if(n%i===0)ok=false;result('#r',`${n} is ${ok?'Prime':'Not Prime'}`,true)};return}
