if(id==='words'){let up=()=>{let t=$('#t').value,w=t.trim()?t.trim().split(/\s+/).length:0;$('#r').innerHTML=`<div class="stats"><div class="stat">Words<b>${w}</b></div><div class="stat">Characters<b>${t.length}</b></div><div class="stat">Lines<b>${t?t.split(/\n/).length:0}</b></div></div>`};$('#t').oninput=up;up();$('#dl').onclick=()=>dltxt($('#t').value,'text.txt')}
