function pages(s,max){let a=new Set;String(s).split(',').forEach(x=>{if(x.includes('-')){let [p,q]=x.split('-').map(Number);if(p>q)[p,q]=[q,p];for(let i=p;i<=q;i++)if(i>=1&&i<=max)a.add(i)}else{let n=Number(x);if(n>=1&&n<=max)a.add(n)}});return[...a].sort((a,b)=>a-b)}
